import * as T from './vendor/three.module.js';
import {generatedMap} from './generated-materials.mjs';
export function createPortableCamp(scene,height,region){let root=null,signature='',fire=null,glow=null;const resources=[];const material=(c,opts={})=>{const m=new T.MeshStandardMaterial({color:c,roughness:.9,...opts});resources.push(m);return m;};
 function clear(){if(root){scene.remove(root);root.traverse(o=>{o.geometry?.dispose();});resources.splice(0).forEach(m=>m.dispose());}root=null;}
 return{sync(c,night,time){const key=c&&c.region===region?JSON.stringify(c):'';if(key!==signature){signature=key;clear();if(key){root=new T.Group();root.userData.kind='portable-mountain-camp';root.position.set(c.x,height(c.x,c.z)+.03,c.z);scene.add(root);const canvas=material('#c8b68f',{map:generatedMap('cozy-materials',0),side:T.DoubleSide}),iron=material('#514c41');for(const side of[-1,1]){const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute([0,1.35,-1.15,side*.95,0,-1.15,0,1.35,1.15,side*.95,0,1.15],3));g.setAttribute('uv',new T.Float32BufferAttribute([0,0,1,0,0,1,1,1],2));g.setIndex([0,2,1,1,2,3]);g.computeVertexNormals();const o=new T.Mesh(g,canvas);o.castShadow=o.receiveShadow=true;root.add(o);}const poles=new T.Mesh(new T.CylinderGeometry(.025,.025,1.4,8),iron);poles.position.set(0,.7,1.15);root.add(poles);fire=new T.Group();fire.position.set(1.8,0,.5);root.add(fire);for(let i=0;i<8;i++){const o=new T.Mesh(new T.IcosahedronGeometry(.15,1),iron);o.position.set(Math.cos(i*Math.PI/4)*.38,.08,Math.sin(i*Math.PI/4)*.38);fire.add(o);}const flame=new T.Mesh(new T.ConeGeometry(.22,.65,12),material('#ffbc59',{emissive:'#f89537',emissiveIntensity:1.2,transparent:true,opacity:.9}));flame.position.y=.35;flame.userData.kind='portable-fire-flame';fire.add(flame);glow=new T.PointLight('#ffc16e',7,9);glow.position.y=.8;fire.add(glow);}}if(root){fire.visible=!!c.fire;fire.children.find(o=>o.userData.kind==='portable-fire-flame').scale.set(1,.9+Math.sin(time*7)*.13,1);glow.intensity=6+Math.sin(time*5)*.5;}}};}
